import type { Position } from '@/types/player';
import { findNFLTeam } from '@/utils/nflTeams';

/**
 * Autograph cards: the rules (no DOM, no React), shared by the store (src/utils/collection.ts, which rolls them inside
 * packs), the canvas renderer (src/components/collection/autograph/) and scripts/simulate_packs.ts.
 *
 * Every autograph is generated by rules, nothing is drawn by hand. A player's HAND is fixed by his name (a seeded hash):
 * one of 36 Google signature fonts × 6 forms (full name, initial and surname, surname only, pro scribble, initials with
 * tails, stacked), plus his own slant, size, tracking, baseline drift, messiness and flourish, so he signs the same way
 * on every card. Each PULL rolls the parallel (where it is signed), the pen and ink, an inscription, a serial number and
 * a rare throwback design, and those rolls set its value:
 *
 *   multiplier = parallel × pen and ink × inscription × serial × throwback      (on top of the card's market price)
 *
 *   Parallels (PARALLELS, odds by weight): Sticker /99 ×3, On-card /50 ×5, Inscribed /25 ×6 (only with something true
 *   to inscribe), Patch /10 ×10, Cut 1/1 ×40 (Hall of Famers only, always broad-nib navy).
 *   Pen and ink (INKS): from black ballpoint ×0.9 to gold paint pen ×1.6; on-card and inscribed autos swap dark ink for
 *   a paint pen (30% gold, else silver) so the signature reads on the card.
 *   Inscription (12% of the other parallels): rings ×1.15 (2+ rings), MVPs ×1.2, Hall of Fame class ×1.25, nickname ×1.3.
 *   Serial: the first of the run (01) ×1.5, the last ×1.2. Throwback (6%): printed in another era's design, ×1.25.
 *
 * The card is TIMELESS (owner: "these stats can change all the time therefore the card should be permanent and
 * timeless"): every career detail it shows (rings, Career Legacy tier, Hall of Fame class, nickname, number, banner team
 * and its colours, his era) is frozen into an AutographSnapshot at the moment of the pull and stored with the autograph;
 * the card renders from that snapshot forever, never from live data. No stat line, record ribbon or stat wall on its face.
 */

// ---------- Seeded randomness ----------

/** FNV-1a 32-bit. */
export const hash = (s: string) => {
  let h = 2166136261 >>> 0;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h >>> 0;
};
/** mulberry32 */
export const rng = (seed: number) => {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
};
export const pickW = <T,>(r: () => number, items: [T, number][]): T => {
  const tot = items.reduce((s, x) => s + x[1], 0);
  let v = r() * tot;
  for (const [k, w] of items) {
    v -= w;
    if (v < 0) return k;
  }
  return items[items.length - 1][0];
};
export const lerp = (a: number, b: number, t: number) => a + (b - a) * t;

// ---------- The hand: fixed by his name ----------

/** Signature fonts (Google Fonts) and a size factor that evens out their x-heights. No marker or comic fonts. */
export const FONTS: { name: string; size: number }[] = (
  [
    ['Mrs Saint Delafield', 1.2], ['Herr Von Muellerhoff', 1.25], ['Monsieur La Doulaise', 0.95], ['Allura', 1.0],
    ['Mr Dafoe', 0.95], ['Meddon', 0.55], ['Ms Madi', 1.15], ['Hurricane', 1.05], ['Comforter', 1.2], ['Mea Culpa', 1.0],
    ['Moon Dance', 1.05], ['My Soul', 1.0], ['Passions Conflict', 1.4], ['Qwitcher Grypen', 1.25], ['Lovers Quarrel', 1.25],
    ['WindSong', 0.6], ['Fuggles', 1.35], ['The Nautigal', 1.15], ['Vujahday Script', 0.95], ['Updock', 1.05],
    ['Kolker Brush', 1.15], ['Babylonica', 1.1], ['Alex Brush', 0.95], ['Great Vibes', 0.95], ['Pinyon Script', 0.85],
    ['Rouge Script', 1.0], ['Sacramento', 1.1], ['Italianno', 1.2], ['Mr De Haviland', 1.15], ['Miss Fajardose', 1.45],
    ['Ruthie', 1.15], ['Corinthia', 1.2], ['Ephesis', 1.1], ['Island Moments', 1.05], ['Lavishly Yours', 1.15], ['Grey Qo', 1.0],
  ] as [string, number][]
).map(([name, size]) => ({ name, size }));

export type SignForm = 'full' | 'initlast' | 'lastonly' | 'scrawl' | 'initials' | 'stacked';
export const FORMS: { id: SignForm; label: string; w: number; k: number }[] = [
  { id: 'full', label: 'Full name', w: 44, k: 1 },
  { id: 'initlast', label: 'Initial and surname', w: 14, k: 1.05 },
  { id: 'lastonly', label: 'Surname only', w: 9, k: 1.1 },
  { id: 'scrawl', label: 'Pro scribble', w: 13, k: 1.2 },
  { id: 'initials', label: 'Initials and tails', w: 11, k: 1.15 },
  { id: 'stacked', label: 'Stacked', w: 9, k: 0.85 },
];

export type Flourish = 'none' | 'swoosh' | 'double' | 'loop' | 'slash' | 'swirl' | 'star' | 'dot';
export const FLOURISH: [Flourish, number][] = [
  ['none', 2], ['swoosh', 3], ['double', 1.2], ['loop', 1.6], ['slash', 1.2], ['swirl', 1.4], ['star', 0.8], ['dot', 1],
];

export interface Hand {
  fontName: string;
  /** CSS font family, quoted */
  font: string;
  mode: SignForm;
  formLabel: string;
  size: number;
}
export interface SignIdentity {
  hand: Hand;
  /** Degrees */
  slant: number;
  size: number;
  track: number;
  drift: number;
  /** 0 (tidy) to 1 (messy) */
  mess: number;
  flourish: Flourish;
  seedA: number;
  seedB: number;
}

const handOf = (font: { name: string; size: number }, form: (typeof FORMS)[number]): Hand => ({
  fontName: font.name,
  font: `"${font.name}"`,
  mode: form.id,
  formLabel: form.label,
  size: font.size * form.k,
});

const identities = new Map<string, SignIdentity>();
/** His handwriting, fixed by his name (the same on every card he ever signs). */
export const identity = (name: string): SignIdentity => {
  const hit = identities.get(name);
  if (hit) return hit;
  const r = rng(hash('sig:' + name));
  const font = FONTS[Math.floor(r() * FONTS.length)];
  const form = pickW(r, FORMS.map((f) => [f, f.w] as [(typeof FORMS)[number], number]));
  const id: SignIdentity = {
    hand: handOf(font, form),
    slant: lerp(-8, 16, r()),
    size: lerp(0.86, 1.14, r()),
    track: lerp(-0.02, 0.06, r()),
    drift: lerp(-0.16, 0.16, r()),
    mess: Math.pow(r(), 1.6),
    flourish: pickW(r, FLOURISH),
    seedA: r(),
    seedB: r(),
  };
  identities.set(name, id);
  return id;
};

// ---------- Pens, inks, parallels, bonuses ----------

export type PenId = 'sharpie' | 'ballpoint' | 'paint' | 'nib' | 'felt';
export interface Pen {
  id: PenId;
  label: string;
  weight: number;
  bleed: number;
  skip?: boolean;
  metallic?: boolean;
  nib?: boolean;
}
export const PENS: Record<PenId, Pen> = {
  sharpie: { id: 'sharpie', label: 'Sharpie', weight: 1, bleed: 1.1 },
  ballpoint: { id: 'ballpoint', label: 'Ballpoint', weight: 0.45, bleed: 0.15, skip: true },
  paint: { id: 'paint', label: 'Paint pen', weight: 0.85, bleed: 0.4, metallic: true },
  nib: { id: 'nib', label: 'Broad nib', weight: 0.7, bleed: 0.5, nib: true },
  felt: { id: 'felt', label: 'Felt tip', weight: 0.9, bleed: 0.8 },
};

/** Ink: a hex colour, metallic 'gold' / 'silver', or 'team' (his club colour, AutographRoll.teamInk). */
export type Ink = string;
/** Every pen and ink a pull can roll: odds (weight w) and value (mult). Rarer inks are worth more. */
export const INKS: { pen: PenId; ink: Ink; label: string; w: number; mult: number; why: string }[] = [
  { pen: 'ballpoint', ink: '#15161b', label: 'Ballpoint, black', w: 10, mult: 0.9, why: 'Thin and fades' },
  { pen: 'ballpoint', ink: '#1d2f9a', label: 'Ballpoint, blue', w: 10, mult: 0.95, why: 'Thin, but blue reads as authentic' },
  { pen: 'sharpie', ink: '#0b0c10', label: 'Sharpie, black', w: 22, mult: 1, why: 'The baseline' },
  { pen: 'sharpie', ink: '#14307a', label: 'Sharpie, blue', w: 14, mult: 1.1, why: 'The collector favourite' },
  { pen: 'felt', ink: 'team', label: 'Felt tip, team colour', w: 16, mult: 1.2, why: "Signed in his club's colour" },
  { pen: 'paint', ink: 'silver', label: 'Paint pen, silver', w: 12, mult: 1.3, why: 'Metallic, shines on dark cards' },
  { pen: 'nib', ink: '#0e1430', label: 'Broad nib, navy', w: 6, mult: 1.4, why: 'Calligraphy thick and thin strokes' },
  { pen: 'nib', ink: '#5a0f14', label: 'Broad nib, oxblood', w: 5, mult: 1.5, why: 'Rare ink, old-school look' },
  { pen: 'paint', ink: 'gold', label: 'Paint pen, gold', w: 5, mult: 1.6, why: 'The rarest ink' },
];
/** The cut auto's pen: a 1/1 is always signed in broad-nib navy. */
export const CUT_INK = INKS.find((x) => x.label === 'Broad nib, navy')!;

export type Parallel = 'sticker' | 'oncard' | 'inscribed' | 'patch' | 'cut';
export const PARALLELS: { id: Parallel; label: string; serial: number; w: number; mult: number; who: string; desc: string }[] = [
  { id: 'sticker', label: 'Sticker auto', serial: 99, w: 57, mult: 3, who: 'Every player', desc: 'Signed on a clear label, applied to the card. The everyday auto.' },
  { id: 'oncard', label: 'On-card auto', serial: 50, w: 26, mult: 5, who: 'Every player', desc: 'Hard-signed straight across the card. Collectors prize these.' },
  { id: 'inscribed', label: 'Inscribed', serial: 25, w: 11, mult: 6, who: 'A player with rings, an MVP, a nickname or a Hall of Fame class', desc: 'Signed and inscribed with something true: rings, MVPs, his Hall of Fame class or nickname.' },
  { id: 'patch', label: 'Patch auto', serial: 10, w: 5.5, mult: 10, who: 'Every player', desc: "A swatch of his club's jersey with the signature beside it." },
  { id: 'cut', label: 'Cut auto 1/1', serial: 1, w: 0.5, mult: 40, who: 'Hall of Famers only', desc: 'A clipped signature on aged paper, framed in the card, in broad-nib navy. One copy exists.' },
];
export const parallelOf = (id: Parallel) => PARALLELS.find((x) => x.id === id)!;

export type InscriptionKind = 'champ' | 'mvp' | 'hof' | 'nickname';
export const INSCRIBE: Record<InscriptionKind, [number, string]> = { nickname: [1.3, 'Nickname'], hof: [1.25, 'Hall of Fame class'], mvp: [1.2, 'MVP count'], champ: [1.15, 'Rings'] };
/** Chance of an inscription on a parallel that is not the Inscribed one. */
export const INSCRIBE_CHANCE = 0.12;
export const serialMult = (n: number, of: number) => (of === 1 ? 1 : n === 1 ? 1.5 : n === of ? 1.2 : 1);
export const THROWBACK = { chance: 0.06, mult: 1.25 };
/** On-card and inscribed autos swap dark ink for a paint pen: this share gold, the rest silver. */
export const PAINT_GOLD_SHARE = 0.3;

// ---------- Card design by era ----------

export type AutoEra = 'leather' | 'broadcast' | 'prizm' | 'night' | 'current';
/** Split along the league's own history (seasons Y1 on). */
export const ERAS: { id: AutoEra; label: string; from: number; to: number; blurb: string }[] = [
  { id: 'leather', label: 'Leather era', from: 1, to: 25, blurb: 'Cream card stock, halftone print, a sepia team tint and a pennant badge.' },
  { id: 'broadcast', label: 'Broadcast era', from: 26, to: 50, blurb: 'A synth sunset over a perspective grid, chrome type.' },
  { id: 'prizm', label: 'Prizm era', from: 51, to: 70, blurb: 'Rainbow refractor foil and light rays, tinted by the club.' },
  { id: 'night', label: 'Night Game era', from: 71, to: 82, blurb: 'Stadium lights and beams over the field, the yard lines below.' },
  { id: 'current', label: 'Current era', from: 83, to: 9999, blurb: 'A giant jersey number knocked out of a mesh jersey texture.' },
];
export const eraOf = (id: AutoEra) => ERAS.find((e) => e.id === id)!;
export const eraOfYear = (y: number) => ERAS.find((e) => y >= e.from && y <= e.to) ?? ERAS[ERAS.length - 1];

// ---------- Prestige: his stature at the pull ----------

export type PrestigeTier = 'legendary' | 'elite' | 'great' | 'hof' | 'rising' | 'none';
export const PRESTIGE: Record<PrestigeTier, { label: string; level: number }> = {
  legendary: { label: 'Legendary', level: 4 },
  elite: { label: 'Elite', level: 3 },
  great: { label: 'Great', level: 2 },
  hof: { label: 'Hall of Famer', level: 2 },
  rising: { label: 'Rising', level: 1 },
  none: { label: '', level: 0 },
};
/** Career Legacy tier: Legendary ≥ 10,000, Elite ≥ 8,500, Great ≥ 7,500, Hall of Famer ≥ 7,300 (members only), Rising = 60 games or fewer with an S or A grade. */
export const prestigeOf = (legacy: number, hof: boolean, games: number, grade: string | null): PrestigeTier => {
  if (legacy >= 10000) return 'legendary';
  if (legacy >= 8500) return 'elite';
  if (legacy >= 7500) return 'great';
  if (legacy >= 7300 && hof) return 'hof';
  if (games <= 60 && grade && /^[SA]/.test(grade)) return 'rising';
  return 'none';
};

// ---------- The frozen snapshot and the roll ----------

/** Everything career-dependent the card shows, frozen at the pull (it never reads live data again). */
export interface AutographSnapshot {
  name: string;
  position: Position;
  /** Banner (signature) team at the pull: nickname ("Falcons") or the raw team label */
  team: string;
  /** Club colours, hex: primary and secondary */
  c1: string;
  c2: string;
  number: number;
  rings: number;
  mvp: number;
  nickname?: string;
  /** A Hall of Famer at the pull */
  hof: boolean;
  /** His Hall of Fame class: "Inaugural" or a season label ("Y87"); missing when unknown */
  hofClass?: string;
  prestige: PrestigeTier;
  /** The season his career centres on, and its era design */
  eraYear: number;
  era: AutoEra;
}

/** One pull's rolls (stored, so a later table change never alters an owned autograph). */
export interface AutographRoll {
  /** Seeds the per-pull pressure, wobble, slant and size jitter */
  seed: number;
  parallel: Parallel;
  pen: PenId;
  ink: Ink;
  /** The club colour a 'team' ink resolves to */
  teamInk: string;
  /** Card design printed (his era, or another for a throwback) */
  era: AutoEra;
  throwback: boolean;
  inscription?: string;
  insKind?: InscriptionKind;
  serial: number;
  of: number;
}

export const inscriptionsOf = (s: Pick<AutographSnapshot, 'rings' | 'mvp' | 'hof' | 'hofClass' | 'nickname'>): [string, InscriptionKind][] => {
  const opts: [string, InscriptionKind][] = [];
  if (s.rings >= 2) opts.push([`${s.rings}x Champ`, 'champ']);
  if (s.mvp >= 1) opts.push([`${s.mvp}x MVP`, 'mvp']);
  if (s.hof && s.hofClass) opts.push([s.hofClass === 'Inaugural' ? 'HOF Inaugural' : `HOF ${s.hofClass}`, 'hof']);
  if (s.nickname) opts.push([s.nickname, 'nickname']);
  return opts;
};

/** Relative luminance of a hex colour. */
export const lum = (hex: string) => {
  const h = hex.replace('#', '');
  const v = [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16) / 255).map((c) => (c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4));
  return 0.2126 * v[0] + 0.7152 * v[1] + 0.0722 * v[2];
};

/** Overrides for a preview (the Art lab): force a parallel, era or pen. */
export interface RollOverrides {
  parallel?: Parallel;
  era?: AutoEra;
  pen?: PenId;
  inscribe?: boolean;
}

/** Every per-pull roll from his snapshot and a seed (deterministic: same seed, same autograph). */
export const rollAutograph = (s: AutographSnapshot, seed: number, over: RollOverrides = {}): AutographRoll => {
  const r = rng(hash(`card:${s.name}:${seed}`));
  const opts = inscriptionsOf(s);
  let parallel = over.parallel ?? pickW(r, PARALLELS.map((x) => [x.id, x.w] as [Parallel, number]));
  if (parallel === 'cut' && !s.hof) parallel = 'oncard';
  if (parallel === 'inscribed' && !opts.length) parallel = 'oncard';
  const pool = over.pen ? INKS.filter((x) => x.pen === over.pen) : INKS;
  const rolled = pickW(r, pool.map((x) => [x, x.w] as [(typeof INKS)[number], number]));
  let pen = rolled.pen;
  let ink = rolled.ink;
  let teamInk = lum(s.c1) < 0.02 ? '#3a3f4a' : s.c1;
  const onCard = parallel === 'oncard' || parallel === 'inscribed';
  if (onCard && ink !== 'gold' && ink !== 'silver') {
    if (ink === 'team' && lum(s.c2) > 0.35) teamInk = s.c2;
    else {
      pen = 'paint';
      ink = r() < PAINT_GOLD_SHARE ? 'gold' : 'silver';
    }
  }
  if (parallel === 'cut') {
    pen = CUT_INK.pen;
    ink = CUT_INK.ink;
  }
  const home = s.era;
  let era = over.era ?? home;
  if (!over.era && r() < THROWBACK.chance) {
    const others = ERAS.filter((e) => e.id !== home);
    era = others[Math.floor(r() * others.length)].id;
  }
  const of = parallelOf(parallel).serial;
  const insR = rng(hash(`ins:${s.name}:${seed}`));
  const ins =
    parallel === 'inscribed'
      ? opts[Math.floor(insR() * opts.length)]
      : over.inscribe !== false && opts.length && r() < INSCRIBE_CHANCE
        ? opts[Math.floor(insR() * opts.length)]
        : null;
  return {
    seed,
    parallel,
    pen,
    ink,
    teamInk,
    era,
    throwback: era !== home,
    ...(ins ? { inscription: ins[0], insKind: ins[1] } : {}),
    serial: of === 1 ? 1 : 1 + Math.floor(r() * of),
    of,
  };
};

export const serialStr = (roll: Pick<AutographRoll, 'serial' | 'of'>) => (roll.of === 1 ? '1/1' : `${String(roll.serial).padStart(2, '0')}/${roll.of}`);
export const inkRowOf = (roll: Pick<AutographRoll, 'parallel' | 'pen' | 'ink'>) =>
  roll.parallel === 'cut' ? CUT_INK : (INKS.find((x) => x.pen === roll.pen && x.ink === roll.ink) ?? INKS.find((x) => x.pen === roll.pen) ?? INKS[2]);

export interface AutographValue {
  total: number;
  parallel: number;
  ink: number;
  inkLabel: string;
  inscription: number;
  serial: number;
  throwback: number;
}
/** What a pull is worth on top of the card's normal price. */
export const autographValue = (roll: AutographRoll): AutographValue => {
  const pl = parallelOf(roll.parallel);
  const inkRow = inkRowOf(roll);
  const ins = roll.insKind ? INSCRIBE[roll.insKind][0] : 1;
  const ser = serialMult(roll.serial, roll.of);
  const tb = roll.throwback ? THROWBACK.mult : 1;
  return { total: pl.mult * inkRow.mult * ins * ser * tb, parallel: pl.mult, ink: inkRow.mult, inkLabel: inkRow.label, inscription: ins, serial: ser, throwback: tb };
};
/** "×3.3", "×12.5" */
export const fmtMult = (v: number) => `×${v >= 10 ? (Math.round(v * 10) / 10).toString() : (Math.round(v * 100) / 100).toString()}`;

// ---------- Freezing a snapshot ----------

const hslToHex = (hsl: string): string | null => {
  const m = hsl.match(/(-?[\d.]+)\s+([\d.]+)%\s+([\d.]+)%/);
  if (!m) return null;
  const h = Number(m[1]) / 360;
  const s = Number(m[2]) / 100;
  const l = Number(m[3]) / 100;
  const f = (n: number) => {
    const k = (n + h * 12) % 12;
    const a = s * Math.min(l, 1 - l);
    const c = l - a * Math.max(-1, Math.min(k - 3, 9 - k, 1));
    return Math.round(c * 255).toString(16).padStart(2, '0');
  };
  return `#${f(0)}${f(8)}${f(4)}`;
};
/** Free agents and unknown clubs: the site's navy and gold. */
const DEFAULT_COLOURS = { c1: '#1a2137', c2: '#ffc83d' };
/** A club's colours as hex (from utils/nflTeams.ts). */
export const teamColours = (team: string | undefined) => {
  const t = findNFLTeam(team);
  const c1 = t ? hslToHex(t.primaryColor) : null;
  const c2 = t ? hslToHex(t.secondaryColor) : null;
  return { label: t?.name ?? (team?.trim() || 'Free agent'), c1: c1 ?? DEFAULT_COLOURS.c1, c2: c2 ?? DEFAULT_COLOURS.c2 };
};

export interface FreezeInput {
  name: string;
  position: Position;
  /** Banner (signature) team */
  team?: string;
  number: number;
  rings: number;
  mvp: number;
  nickname?: string;
  careerLegacy: number;
  games: number;
  hof: boolean;
  /** content.json hofClasses label ("Inaugural class", "Y87") */
  hofClass?: string;
  /** Skill grade letter ("S", "A+"), only needed for the Rising tier */
  grade?: string | null;
  /** The season his career centres on */
  eraYear: number;
}

/** Freezes the career details an autograph shows, as of now. */
export const freezeSnapshot = (p: FreezeInput): AutographSnapshot => {
  const { label, c1, c2 } = teamColours(p.team);
  const cls = p.hof && p.hofClass ? (/^inaugural/i.test(p.hofClass) ? 'Inaugural' : p.hofClass.replace(/\s*class$/i, '')) : undefined;
  const year = Math.max(1, Math.round(p.eraYear) || 1);
  return {
    name: p.name,
    position: p.position,
    team: label,
    c1,
    c2,
    number: Math.max(0, Math.round(p.number) || 0),
    rings: Math.max(0, p.rings || 0),
    mvp: Math.max(0, p.mvp || 0),
    ...(p.nickname?.trim() ? { nickname: p.nickname.trim() } : {}),
    hof: p.hof,
    ...(cls ? { hofClass: cls } : {}),
    prestige: prestigeOf(p.careerLegacy || 0, p.hof, p.games || 0, p.grade ?? null),
    eraYear: year,
    era: eraOfYear(year).id,
  };
};

// ---------- Validation (stored autographs) ----------

const HEX = /^#[0-9a-f]{6}$/i;
const POSITIONS: Position[] = ['QB', 'RB', 'WR', 'TE', 'OL', 'LB', 'DB', 'DL'];
const n0 = (x: unknown) => (typeof x === 'number' && Number.isFinite(x) && x >= 0 ? Math.floor(x) : 0);
const str = (x: unknown) => (typeof x === 'string' && x.trim() ? x : undefined);
const isInk = (x: unknown): x is Ink => typeof x === 'string' && (x === 'gold' || x === 'silver' || x === 'team' || HEX.test(x));

export const parseSnapshot = (x: unknown): AutographSnapshot | null => {
  const s = x as Partial<AutographSnapshot> | null;
  if (!s || typeof s !== 'object' || !str(s.name) || !POSITIONS.includes(s.position as Position)) return null;
  if (!HEX.test(s.c1 ?? '') || !HEX.test(s.c2 ?? '')) return null;
  const era = ERAS.some((e) => e.id === s.era) ? s.era! : eraOfYear(n0(s.eraYear) || 1).id;
  const nickname = str(s.nickname);
  const hofClass = str(s.hofClass);
  return {
    name: s.name!,
    position: s.position as Position,
    team: str(s.team) ?? 'Free agent',
    c1: s.c1!,
    c2: s.c2!,
    number: n0(s.number),
    rings: n0(s.rings),
    mvp: n0(s.mvp),
    ...(nickname ? { nickname } : {}),
    hof: !!s.hof,
    ...(hofClass && s.hof ? { hofClass } : {}),
    prestige: (s.prestige && s.prestige in PRESTIGE ? s.prestige : 'none') as PrestigeTier,
    eraYear: n0(s.eraYear) || 1,
    era,
  };
};

export const parseRoll = (x: unknown): AutographRoll | null => {
  const r = x as Partial<AutographRoll> | null;
  if (!r || typeof r !== 'object') return null;
  if (!PARALLELS.some((p) => p.id === r.parallel) || !(typeof r.pen === 'string' && r.pen in PENS) || !isInk(r.ink)) return null;
  if (!ERAS.some((e) => e.id === r.era)) return null;
  const of = parallelOf(r.parallel!).serial;
  const serial = Math.min(of, Math.max(1, n0(r.serial)));
  const insKind = typeof r.insKind === 'string' && r.insKind in INSCRIBE ? r.insKind : undefined;
  const inscription = str(r.inscription);
  return {
    seed: n0(r.seed),
    parallel: r.parallel!,
    pen: r.pen as PenId,
    ink: r.ink!,
    teamInk: HEX.test(r.teamInk ?? '') ? r.teamInk! : '#3a3f4a',
    era: r.era!,
    throwback: !!r.throwback,
    ...(inscription && insKind ? { inscription, insKind } : {}),
    serial,
    of,
  };
};
